package hospital.vista.paginas;
import hospital.controlador.HospitalController;import hospital.modelos.*;import hospital.vista.atomos.UiButton;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.time.format.DateTimeFormatter;
/** Página principal con módulos visuales para pacientes, habitaciones e historial. */
public class HospitalPage extends JPanel {
 private final HospitalController c;private final CardLayout layout=new CardLayout();private final JPanel pages=new JPanel(layout);
 private final DefaultTableModel pm=model("Identificación","Nombre","Edad","Triage","Motivo"),hm=model("Habitación","Piso","Posición","Estado","Paciente"),rm=model("Fecha","Acción","Habitación","Paciente","Identificación");
 public HospitalPage(HospitalController c){this.c=c;setLayout(new BorderLayout());JPanel bar=new JPanel(new FlowLayout(FlowLayout.LEFT));addNav(bar,"Pacientes","p");addNav(bar,"Habitaciones","h");addNav(bar,"Historial","r");add(bar,BorderLayout.NORTH);pages.add(tablePage(pm,()->loadPatients(),new String[]{"Registrar paciente"}),"p");pages.add(tablePage(hm,()->loadRooms(),new String[]{"Asignar","Dar salida","Matriz"}),"h");pages.add(tablePage(rm,()->loadHistory(),new String[]{"Actualizar"}),"r");add(pages,BorderLayout.CENTER);loadPatients();}
 private static DefaultTableModel model(String...cols){return new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}};}
 private JPanel tablePage(DefaultTableModel m,Runnable refresh,String[] actions){JPanel p=new JPanel(new BorderLayout(0,10));JPanel tools=new JPanel(new FlowLayout(FlowLayout.LEFT));for(String a:actions){UiButton b=new UiButton(a);b.addActionListener(e->{if(a.equals("Registrar paciente"))register();else if(a.equals("Asignar"))assign();else if(a.equals("Dar salida"))discharge();else if(a.equals("Matriz"))JOptionPane.showMessageDialog(this,c.matriz());else refresh.run();});tools.add(b);}p.add(tools,BorderLayout.NORTH);JTable t=new JTable(m);t.setRowHeight(28);p.add(new JScrollPane(t),BorderLayout.CENTER);return p;}
 private void addNav(JPanel bar,String label,String key){UiButton b=new UiButton(label);b.addActionListener(e->{layout.show(pages,key);if(key.equals("p"))loadPatients();if(key.equals("h"))loadRooms();if(key.equals("r"))loadHistory();});bar.add(b);}
 private void register(){JTextField id=new JTextField(),name=new JTextField(),age=new JTextField(),triage=new JTextField(),reason=new JTextField();Object[] f={"Identificación",id,"Nombre",name,"Edad",age,"Triage (1-5)",triage,"Motivo",reason};if(JOptionPane.showConfirmDialog(this,f,"Registrar paciente",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)try{c.registrarPaciente(id.getText().trim(),name.getText().trim(),Integer.parseInt(age.getText()),Integer.parseInt(triage.getText()),reason.getText().trim());loadPatients();}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Validación",JOptionPane.WARNING_MESSAGE);}}
 private void assign(){JTextField id=new JTextField(),n=new JTextField();Object[] f={"Identificación",id,"Habitación (1-30)",n};if(JOptionPane.showConfirmDialog(this,f,"Asignar habitación",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)try{c.asignarHabitacion(id.getText().trim(),Integer.parseInt(n.getText()));loadRooms();}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage());}}
 private void discharge(){String id=JOptionPane.showInputDialog(this,"Identificación del paciente");if(id!=null)try{c.darSalida(id.trim());loadRooms();}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage());}}
 private void loadPatients(){pm.setRowCount(0);for(Paciente p:c.pacientes())pm.addRow(new Object[]{p.getIdentificacion(),p.getNombre(),p.getEdad(),p.getNivelTriage(),p.getMotivoIngreso()});}
 private void loadRooms(){hm.setRowCount(0);for(Habitacion h:c.habitaciones())hm.addRow(new Object[]{h.getNumero(),h.getPiso(),h.getPosicion(),h.isOcupada()?"Ocupada":"Disponible",h.getPaciente()==null?"—":h.getPaciente().getNombre()});}
 private void loadHistory(){rm.setRowCount(0);for(RegistroHistorial r:c.historial())rm.addRow(new Object[]{r.getFechaHora().format(DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm:ss")),r.getAccion(),r.getNumeroHabitacion(),r.getNombrePaciente(),r.getIdentificacionPaciente()});}
}